'You' => 'Vous',
'Enable_Pos_Salesperson_Switch' => 'Changer de vendeur pendant l\'encaissement',
'Enable_Pos_Salesperson_Switch_Hint' => 'Affiche un sélecteur de vendeur sur l\'écran du POS afin qu\'une vente puisse être attribuée à un autre employé sans se déconnecter. Le vendeur sélectionné est enregistré sur la facture et utilisé dans les rapports de ventes ; la session POS active reste inchangée.',

'Wallet_Payment_Method_Missing' => 'Le mode de paiement Portefeuille est manquant',
'Wallet_Payment_Method_Missing_Help' => 'Aucun mode de paiement nommé exactement "Wallet" n\'a été trouvé. Le paiement par portefeuille du POS est identifié par ce nom : les clients ne pourront donc pas payer avec leur portefeuille tant que vous n\'aurez pas ajouté ici un mode de paiement nommé "Wallet" :',

'Show_Previous_Dues_Line' => 'Afficher la ligne des impayés précédents',
'Show_Previous_Dues_Line_Desc' => 'Solde dû par le client avant cette vente. Imprimé uniquement s\'il est supérieur à zéro.',
'Show_Net_Balance_Line' => 'Afficher la ligne du solde net',
'Show_Net_Balance_Line_Desc' => 'Impayés précédents plus le reste dû sur cette vente. Imprimé uniquement lorsque les impayés précédents sont supérieurs à zéro.',

'QZ_Tray_Printer' => 'QZ Tray (imprimante sur cet ordinateur)',
'QZ_Printer_Name_Hint' => 'Le nom de l\'imprimante tel qu\'il apparaît sur l\'ordinateur qui exécute QZ Tray. Laissez vide pour utiliser l\'imprimante par défaut de cet ordinateur. Cliquez sur ⟳ pour détecter les imprimantes.',
'QZ_Not_Running' => 'QZ Tray n\'est pas lancé sur cet ordinateur. Installez-le depuis qz.io et laissez-le ouvert, puis autorisez ce site lorsque QZ vous le demande.',
'Detect_Printers' => 'Détecter les imprimantes',
'QZ_Download_Cert' => 'Télécharger le certificat (override.crt)',
'QZ_Setup_Title' => 'Comment configurer l\'impression avec QZ Tray (une seule fois, sur chaque ordinateur qui imprime des étiquettes)',
'QZ_Step_Install' => '1. Installez QZ Tray sur cet ordinateur : téléchargez-le gratuitement sur qz.io, lancez-le et laissez-le ouvert (il se trouve dans la zone de notification sous Windows ou dans la barre de menus sous macOS).',
'QZ_Step_Connect' => '2. Branchez votre imprimante d\'étiquettes en USB et vérifiez qu\'elle est installée dans le système (Windows : Paramètres > Imprimantes et scanners — macOS : Réglages Système > Imprimantes et scanners).',
'QZ_Step_Detect' => '3. Cliquez sur le bouton ⟳ à côté de « Nom de l\'imprimante » ci-dessus pour détecter les imprimantes de cet ordinateur, puis sélectionnez votre imprimante d\'étiquettes. Laissez le champ vide pour utiliser l\'imprimante par défaut de l\'ordinateur.',
'QZ_Step_Cert' => '4. Pour imprimer sans fenêtre d\'autorisation, téléchargez le certificat ci-dessous et copiez-le dans le dossier d\'installation de QZ Tray en le renommant override.crt (Windows : C:\\Program Files\\QZ Tray — macOS : /Applications/QZ Tray.app/Contents/Resources — Linux : /opt/qz-tray). Quittez ensuite QZ Tray et relancez-le.',
'QZ_Step_Test' => '5. Cliquez sur « Imprimer une étiquette de test » ci-dessous. Si QZ Tray demande une autorisation, cliquez sur Allow ; avec le certificat installé, il ne la demandera plus.',
'QZ_Step_Save' => '6. Cliquez sur Envoyer pour enregistrer ces paramètres. Les étiquettes de la page Imprimer les codes-barres s\'imprimeront désormais directement sur cette imprimante, sans boîte de dialogue d\'impression du navigateur.',
'QZ_Setup_Note' => 'QZ Tray s\'exécute sur l\'ordinateur depuis lequel vous naviguez : cela fonctionne donc même si Stocky est hébergé sur un serveur distant. Chaque ordinateur qui imprime des étiquettes doit avoir QZ Tray installé.',

// PWA settings tab — installable app identity
'PWA_Enabled' => 'Activer l\'application installable',
'PWA_Enabled_Help' => 'Permet aux navigateurs de proposer l\'installation de cette application sur téléphones, tablettes et ordinateurs, et conserve les pages hors ligne en cache. La désactivation supprime l\'invitation à installer partout et vide le cache à la prochaine visite.',
'PWA_Identity' => 'Identité de l\'application',
