'PWA_App_Name' => 'Nom de l\'application',
'PWA_App_Name_Help' => 'Affiché dans l\'invitation à installer et dans la liste des applications. Laissez vide pour utiliser le nom défini dans les paramètres d\'apparence.',
'PWA_Short_Name' => 'Nom court',
'PWA_Short_Name_Help' => 'Affiché sous l\'icône sur les écrans d\'accueil, où les noms longs sont tronqués. Laissez vide pour utiliser la partie du nom de l\'application située avant « | ».',
