'Label_Render_Mode' => 'Rendu de l\'étiquette',
'Label_Render_Mode_Hint' => 'Façon dont l\'étiquette est dessinée. Polices de l\'imprimante est le plus rapide et donne le code-barres le plus net, mais n\'imprime que les caractères latins de base dans la police propre à l\'imprimante. Image d\'aperçu reproduit exactement votre modèle d\'étiquette — la police choisie, n\'importe quelle langue — comme le font les logiciels d\'étiquetage spécialisés.',
'Render_Native' => 'Polices de l\'imprimante (le plus rapide)',
'Render_Raster' => 'Image d\'aperçu (rendu exact)',
'Label_Width_Mm' => 'Largeur de l\'étiquette (mm)',
'Label_Height_Mm' => 'Hauteur de l\'étiquette (mm)',
'Label_Size_Hint' => 'La taille physique d\'une étiquette sur le rouleau. Elle doit correspondre exactement aux étiquettes chargées : une mauvaise taille fait chercher l\'espacement au mauvais endroit, et chaque étiquette s\'imprime de plus en plus décalée.',
'Calibrate_Labels' => 'Calibrer les étiquettes',
'Calibrate_Labels_Hint' => 'L\'imprimante fait défiler quelques étiquettes pour mesurer l\'étiquette et l\'espacement. À lancer une fois après le chargement d\'un nouveau rouleau, ou lorsque la position d\'impression dérive.',
'Calibration_Sent' => 'Calibrage lancé : l\'imprimante va faire défiler quelques étiquettes vierges pour les mesurer. Quand elle s\'arrête, lancez une impression de test.',
'Label_Printer_Dpi' => 'Résolution de la tête d\'impression',
'Label_Printer_Dpi_Hint' => 'La plupart des imprimantes d\'étiquettes sont en 203 dpi. Pas sûr ? Utilisez le bouton « Trouver la résolution » ci-dessous : il imprime la réponse.',
'Find_Resolution' => 'Trouver la résolution',
'Find_Resolution_Hint' => 'Imprime deux étiquettes marquées 203 et 300. La bonne montre un rectangle complet sur l\'étiquette avec une petite marge régulière sur les quatre côtés ; la mauvaise a des bords manquants ou déborde sur l\'étiquette suivante.',
'Dpi_Test_Sent' => 'Deux étiquettes marquées 203 et 300 sont en cours d\'impression. La bonne montre un rectangle complet avec une petite marge régulière sur les quatre côtés : réglez « Résolution de la tête d\'impression » sur ce nombre et enregistrez.',
'Label_Offset_X' => 'Décalage horizontal (mm)',
'Label_Offset_X_Hint' => 'Déplace l\'impression latéralement sur l\'étiquette. À utiliser lorsque le texte est coupé sur un bord latéral, p. ex. 2.5 lorsque l\'étiquette blanche est centrée sur un support plus large. Ajustez par pas de 0.5.',
'Label_Offset_Y' => 'Décalage vertical (mm)',
'Label_Offset_Y_Hint' => 'Déplace l\'impression le long de l\'étiquette. Augmentez si le haut du modèle est coupé ou manquant ; diminuez s\'il commence trop bas.',
'Feed_To_Tear' => 'Avancer jusqu\'au bord de déchirement',
'Feed_To_Tear_Hint' => 'Fait avancer l\'étiquette jusqu\'à la barre de déchirement après chaque impression. Laissez désactivé si les étiquettes s\'impriment décalées vers le bas ou à cheval sur deux étiquettes : beaucoup d\'imprimantes ne reculent pas avant l\'étiquette suivante.',
