'Ord_Guide_Lifecycle_Cancelled' => 'La commande a été abandonnée avant confirmation : aucune vente n\'a été créée et aucun stock déduit.',
'Ord_Guide_PaymentStatus_Tip' => 'Défini lors du paiement et non modifiable ici. Cliquez pour voir comment enregistrer le paiement.',
'Ord_Guide_Payment_Title' => 'Statut du paiement',
'Ord_Guide_Payment_Intro' => 'Cette colonne enregistre le mode de paiement choisi par le client lors de la commande. Elle est définie par la boutique et ne peut pas être modifiée depuis cette page ; l\'argent lui-même est suivi sur la vente créée par la confirmation de la commande.',
'Ord_Guide_Payment_Paid' => 'Le client a déjà payé en ligne via une passerelle de paiement. Confirmer la commande crée la vente comme Payée et enregistre le paiement pour vous : rien d\'autre à faire.',
'Ord_Guide_Payment_Pending' => 'Paiement à la livraison, virement bancaire ou autre paiement différé. Confirmer la commande crée la vente comme Non payée : vous enregistrez l\'argent vous-même une fois encaissé, voir les étapes ci-dessous.',
'Ord_Guide_Payment_Failed' => 'La passerelle a refusé le paiement ou le client l\'a abandonné. La commande est annulée automatiquement.',
'Ord_Guide_MarkPaid_Title' => 'Passer un paiement d\'en attente à payé',
'Ord_Guide_MarkPaid_Step1' => 'Confirmez d\'abord la commande ici : c\'est la confirmation qui crée la vente.',
'Ord_Guide_MarkPaid_Step2' => 'Ouvrez Ventes > Toutes les ventes et retrouvez cette vente (même client, et la page de détails indique la commande en ligne dont elle provient).',
'Ord_Guide_MarkPaid_Step3' => 'Ouvrez le menu d\'actions de la ligne et choisissez Créer un paiement.',
'Ord_Guide_MarkPaid_Step4' => 'Saisissez le montant, le mode de paiement et la date, puis enregistrez. La vente passe d\'elle-même à Partiel ou Payée selon le montant.',
'Ord_Guide_MarkPaid_Note' => 'Le statut de paiement affiché ici continue de refléter le choix fait à la commande et reste inchangé. La vente est l\'enregistrement comptable, et c\'est elle qui alimente vos rapports de paiements et de bénéfices. Utilisez Afficher les paiements sur la vente pour vérifier ou modifier ce que vous avez saisi.',
'Ord_Guide_Notes_Title' => 'Bon à savoir',
'Ord_Guide_Note_Warehouse' => 'L\'entrepôt choisi à la confirmation détermine d\'où provient le stock. Les entrepôts qui ne peuvent pas couvrir toute la commande sont marqués Rupture de stock dans cette liste.',
'Ord_Guide_Note_Preorder' => 'Les articles en précommande ignorent le contrôle de stock : une commande qui en contient peut être confirmée même si la quantité n\'est pas encore disponible.',
'Ord_Guide_Note_Flagged' => 'Une étiquette Signalée signifie que la commande a déclenché un contrôle anti-fraude lors du paiement. Survolez l\'étiquette pour voir la raison et examinez la commande avant de la confirmer.',
'Ord_Guide_Note_Cancel' => 'L\'annulation n\'est possible que tant que la commande est en attente. Une fois confirmée, annulez-la via la vente ou un retour client.',


