// Variants guide drawer (product form).
'Guide' => 'Guide',
'Variants_Guide' => 'Guide des variantes',
'VG_Intro' => 'Un produit variable est vendu sous plusieurs variantes. Créez-les à partir d’options (recommandé) ou sous forme d’une simple liste de noms. Chaque variante possède son propre code, ses prix, son image et son stock.',
'VG_Options_Title' => 'Mode options (Couleur, Taille...)',
'VG_Opt_Step1' => 'Laissez l’interrupteur de l’en-tête de la carte sur « Options ».',
'VG_Opt_Step2' => 'Saisissez un nom d’option, comme Couleur ou Taille, ou choisissez l’une des suggestions.',
'VG_Opt_Step3' => 'Saisissez une valeur (par exemple Rouge) et appuyez sur Entrée. Répétez pour chaque valeur ; une virgule sépare aussi les valeurs. Cliquez sur le x d’une valeur pour la retirer.',
'VG_Opt_Step4' => 'Cliquez sur « Ajouter une option » pour une deuxième ou une troisième option (3 options maximum).',
'VG_Opt_Step5' => 'Cliquez sur « Générer les variantes ». Une ligne est créée par combinaison et son nom est construit automatiquement, par exemple « Rouge / S ».',
'VG_Opt_Step6' => 'Saisissez le coût et le prix sur chaque ligne, ou saisissez une valeur dans « Appliquer à tous » puis cliquez sur Coût ou Prix pour la copier dans toutes les lignes.',
'VG_Opt_Step7' => 'Les codes sont générés automatiquement. Saisissez le vôtre ou cliquez sur l’icône d’actualisation pour en générer un autre.',
'VG_Opt_Step8' => 'Facultatif : cochez « Pastilles de couleur » sur une option et choisissez une couleur pour chaque valeur ; la boutique l’affiche sous forme de point coloré.',
'VG_Rows_Title' => 'Lignes de variantes',
'VG_Rows_Text' => 'Chaque ligne comporte une image, un code, un code-barres, un coût, un prix, un prix de gros et un prix de vente minimum. Lors de la création d’un produit, vous pouvez aussi saisir le stock initial par entrepôt pour chaque variante. Une étiquette « Incomplet » signifie qu’il manque à la ligne une valeur pour l’une des options.',
'VG_List_Title' => 'Mode liste simple',
'VG_List_Text' => 'Saisissez un nom de variante et appuyez sur Entrée (ou cliquez sur Ajouter) pour ajouter une ligne, puis renseignez son code et ses prix. C’est le fonctionnement classique, qui reste disponible pour les produits existants.',
'VG_Edit_Title' => 'Modification ultérieure',
'VG_Edit_1' => 'Ajoutez une valeur et cliquez sur « Générer les variantes » : seules les combinaisons manquantes sont ajoutées. Les lignes existantes conservent leurs codes, leurs prix et leur historique.',
'VG_Edit_2' => 'Retirer une valeur ou une option supprime les lignes qui l’utilisent. Les lignes déjà enregistrées sont supprimées à l’enregistrement du produit, après confirmation.',
'VG_Edit_3' => 'Une variante qui a encore du stock ne peut pas être supprimée. Ajustez ou transférez d’abord son stock.',
'VG_Edit_4' => 'Passer en « Liste simple » conserve les lignes et leurs noms, mais supprime les définitions d’options.',
'VG_Store_Title' => 'Sur la boutique en ligne',
'VG_Store_Text' => 'Les clients choisissent une valeur par option, par exemple la Couleur puis la Taille. Les combinaisons inexistantes sont désactivées et celles en rupture de stock sont barrées. C’est la variante choisie qui est ajoutée au panier.',
