'Warehouse_Logo_Help' => 'Logo imprimé sur les factures et les tickets POS de cet entrepôt. Laissez vide pour utiliser le logo de l’entreprise.',
'Warehouse_Invoice_Footer_Help' => 'Note supplémentaire imprimée en bas des factures émises par cet entrepôt.',
