'Enable_Warehouse_Letterhead_Hint' => 'Imprime l’entrepôt émetteur sur les factures, les tickets POS et la page de facture publique : son nom remplace celui de l’entreprise, et son adresse, son téléphone, son e-mail, son logo et sa note de bas de page remplacent ceux de l’entreprise. Tout champ laissé vide pour l’entrepôt reprend les paramètres globaux de l’entreprise.',
'Warehouse_Letterhead_Receipt_Notice' => 'L’en-tête d’entrepôt est activé : le nom, l’adresse et le téléphone du magasin imprimés sur un vrai ticket proviennent de l’entrepôt qui a émis la vente, et sa note de bas de page est ajoutée sous la note client.',
