'Set_Sidebar_Intro_Title' => 'Glissez-déposez pour réorganiser la barre latérale',
'Set_Sidebar_Intro_Desc' => 'Réorganisez les modules, les éléments au sein d’un module, ou faites glisser un élément vers un autre module. Les modules restent toujours au niveau supérieur et les éléments ne peuvent pas devenir des modules. L’organisation enregistrée s’applique à tous les utilisateurs.',
