'Upd_Note_Code_Changes_Lost' => 'Remarque 1 : si vous avez modifié le code manuellement, vos modifications seront perdues.',
'Upd_Manual_Steps_Intro' => 'Veuillez suivre ces étapes pour mettre à jour votre application',
'Upd_Note_Permission_Only' => 'Remarque 2 : seul un administrateur ou un utilisateur disposant de l’autorisation « {perm} » peut mettre à jour le système',
'Upd_Manual_Step_Backup_Db' => 'Sauvegardez votre base de données. Allez dans {backup}, cliquez sur Générer une sauvegarde — vous la trouverez dans {path} — ou exportez votre base de données depuis PhpMyAdmin et enregistrez-la sur votre PC.',
'Upd_Manual_Step_Backup_Files' => 'Sauvegardez vos fichiers avant la mise à jour.',
'Upd_Manual_Step_Download' => 'Téléchargez la dernière version depuis votre compte CodeCanyon et décompressez-la.',
'Upd_Manual_Step_Remove' => 'Supprimez les anciens fichiers, {except} :',
'Upd_Except' => 'sauf',
'Upd_File_Label' => 'fichier : {name}',
'Upd_Folder_Label' => 'dossier : {name}',
'Upd_Manual_Step_Reupload' => 'Téléversez de nouveau les fichiers et dossiers de la nouvelle mise à jour, {except} les trois mêmes chemins ci-dessus.',
'Upd_Manual_Step_Visit' => 'Rendez-vous sur {url} pour mettre à jour votre base de données.',
'Upd_Manual_Step_Clear_Cache' => 'Videz complètement le cache de votre navigateur.',
'Upd_Manual_Step_Done' => 'C’est terminé ! Profitez de l’application mise à jour.',
'Upd_Note_Blank_Pages' => 'Remarque : si certaines pages ne se chargent pas ou restent vides, assurez-vous d’avoir vidé le cache de votre navigateur.',
'Upd_Guide_Before_Title' => '1. Avant la mise à jour',
'Upd_Guide_Before_Download' => 'Téléchargez le {package} de l’application depuis votre compte CodeCanyon ({path}). Ne le décompressez pas — l’outil de mise à jour a besoin du ZIP tel qu’il a été téléchargé.',
'Upd_Latest_Full_Zip' => 'dernier package ZIP complet',
'Upd_Guide_Before_Admin' => 'Assurez-vous d’être connecté en tant qu’administrateur disposant de l’autorisation {perm}. Personne d’autre ne peut voir ni lancer l’outil de mise à jour.',
'Upd_Guide_Before_Quiet' => 'Choisissez un moment calme : pendant la mise à jour, l’application passe brièvement en mode maintenance et les autres utilisateurs n’y ont plus accès.',
'Upd_Guide_Before_No_Manual' => 'Vous n’avez {not} besoin de sauvegarder manuellement, de décompresser des fichiers, d’exécuter des commandes, de modifier des fichiers de configuration ni de toucher à la base de données — l’outil de mise à jour s’en charge automatiquement. (Une sauvegarde manuelle supplémentaire ne fait bien sûr jamais de mal.)',
'Upd_Not' => 'pas',
'Upd_Guide_Code_Overwritten' => 'Si vous avez modifié manuellement le code de l’application, vos modifications seront écrasées par la mise à jour. Vos données, fichiers téléversés, paramètres et votre fichier .env sont toujours conservés.',
'Upd_Guide_Running_Title' => '2. Lancer la mise à jour',
'Upd_Guide_Run_Open' => 'Ouvrez {path} (cette page) et restez sur l’onglet {tab}.',
'Upd_Guide_Run_Upload' => '{upload} : cliquez ou faites glisser le package téléchargé dans la zone de téléversement. Les fichiers volumineux sont envoyés par petits morceaux, ce qui fonctionne aussi sur les hébergements mutualisés aux limites de téléversement réduites. Une somme de contrôle protège contre les téléversements corrompus ou incomplets.',
'Upd_Upload_The_Zip' => 'Téléverser le ZIP',
'Upd_Guide_Run_Validation' => '{auto} après le téléversement (vous pouvez la relancer avec le bouton {button}). Le système vérifie : l’intégrité du ZIP, la structure et l’exhaustivité du package, la compatibilité de version (les retours à une version antérieure sont refusés), la version de PHP et les extensions requises, les permissions des fichiers, l’espace disque libre, la connexion à la base de données, la configuration, et qu’aucune autre mise à jour n’est en cours.',
'Upd_Validation_Runs_Automatically' => 'La validation s’exécute automatiquement',
'Upd_Guide_Run_Review' => 'Examinez le panneau {panel}. Le bouton {button} n’apparaît que lorsque toutes les vérifications critiques sont réussies. Si une vérification échoue, le message indique exactement ce qu’il faut corriger.',
'Upd_Guide_Run_Click' => 'Cliquez sur {button} et confirmez. Ensuite, il vous suffit de {keep} et de suivre la barre de progression. Le système effectue, dans l’ordre :',
'Upd_Keep_Page_Open' => 'garder cette page ouverte',
'Upd_Guide_Phase_Backup' => '{label} — un export complet de la base de données, un ZIP de tous les fichiers de l’application que la mise à jour peut modifier et une copie de {env} sont créés et {verified}. Vos fichiers téléversés ({images}) et {storage} ne sont jamais touchés par une mise à jour ; ils ne sont donc pas archivés. Si une sauvegarde ne peut pas être créée, la mise à jour s’arrête ici et rien n’est modifié.',
'Upd_Verified' => 'vérifiés',
'Upd_Guide_Phase_Prepare' => '{label} — la nouvelle version est décompressée dans une zone de préparation et validée à nouveau. L’application en production reste intacte.',
'Upd_Guide_Phase_Maintenance' => '{label} — le mode maintenance est activé ; les visiteurs voient un écran convivial « Nous revenons tout de suite ».',
'Upd_Guide_Phase_Files' => '{label} — les nouveaux fichiers sont mis en place quasi instantanément ; les anciens fichiers sont conservés de côté pour un éventuel retour arrière. Les chemins protégés ({env}, {storage}, {images}) ne sont jamais remplacés.',
'Upd_Guide_Phase_Database' => '{label} — les migrations s’exécutent, puis les autorisations, traductions et modèles sont actualisés.',
'Upd_Guide_Phase_Cache' => '{label} — tous les caches sont vidés et reconstruits.',
'Upd_Guide_Phase_Verify' => '{label} — des contrôles de santé confirment que la nouvelle version démarre, que la base de données fonctionne, que toutes les migrations ont été exécutées et que la configuration est valide.',
'Upd_Guide_Phase_Done' => '{label} — le mode maintenance est désactivé et les fichiers temporaires sont nettoyés.',
'Upd_Guide_Run_Success' => 'Lorsque vous voyez {success}, cliquez sur {reload} et forcez l’actualisation de votre navigateur ({keys}) afin de charger les nouvelles ressources du panneau d’administration.',
'Upd_Update_Successful_Short' => 'Mise à jour réussie',
'Upd_Guide_No_Internet' => 'Aucune connexion Internet n’est nécessaire pendant la mise à jour — tout provient du ZIP téléversé. Perdre votre connexion ou fermer le navigateur n’interrompt PAS la mise à jour : le serveur se souvient exactement de l’endroit où il s’est arrêté.',
'Upd_Guide_Wrong_Title' => '3. En cas de problème',
'Upd_Guide_Wrong_Rollback' => '{label} — si une erreur survient après le début de la modification des fichiers (erreur de décompression, échec de migration, contrôle de santé échoué, disque plein, …), le système restaure automatiquement les fichiers précédents et la base de données à partir de la sauvegarde vérifiée, désactive le mode maintenance et affiche {message}. Vous revenez exactement à votre point de départ.',
'Upd_Automatic_Rollback' => 'Retour arrière automatique',
'Upd_Failed_Previous_Restored' => 'Échec de la mise à jour — version précédente restaurée',
'Upd_Guide_Wrong_Interrupted' => '{label} (redémarrage du serveur, délai dépassé, navigateur fermé, coupure de courant) — lorsque vous rouvrez cette page, une bannière rouge propose deux choix sûrs : {resume} (reprend à l’étape exacte où elle s’est arrêtée) ou {rollback} (restaure la version précédente à partir de la sauvegarde).',
'Upd_Interrupted_Update' => 'Mise à jour interrompue',
'Upd_Guide_Wrong_Unreachable' => '{label} — utilisez la {console} autonome à l’adresse {path}. Elle fonctionne même lorsque le site est en mode maintenance ou que les ressources du panneau d’administration sont endommagées, et propose les mêmes actions Continuer / Revenir en arrière. Un lien discret « Accès administrateur » figure également en bas de l’écran de maintenance.',
'Upd_Admin_Unreachable' => 'Panneau d’administration inaccessible',
'Upd_Recovery_Console' => 'console de récupération',
'Upd_Guide_Wrong_Locked_Out' => '{label} — pendant une mise à jour, cette page affiche un {link}. Enregistrez-le si vous devez revenir (par exemple après l’expiration de votre session) ; il vous permet de passer l’écran de maintenance pour vous reconnecter.',
'Upd_Locked_Out_Maintenance' => 'Accès bloqué par le mode maintenance',
'Upd_Bypass_Link' => 'lien de contournement',
'Upd_Guide_Wrong_Concurrent' => '{label} — il verra {message} Une seule mise à jour peut s’exécuter à la fois.',
'Upd_Another_Admin_Updating' => 'Un autre administrateur tente une mise à jour en même temps',
'Upd_Guide_Backups_Title' => '4. Sauvegardes et restauration',
'Upd_Guide_Backups_Created' => 'Chaque mise à jour crée une sauvegarde {before} de toucher à quoi que ce soit : tous les fichiers de l’application que la mise à jour peut remplacer, une copie de {env} et un export complet de la base de données. Les fichiers téléversés et {storage} ne sont jamais modifiés par une mise à jour et n’en font donc pas partie — conservez vos propres sauvegardes de ces éléments. Les sauvegardes se trouvent dans {path} et ne sont jamais accessibles depuis le web.',
'Upd_Before' => 'avant',
'Upd_Guide_Backups_Panel' => 'Le panneau {panel} de l’onglet {tab} les liste avec leur date, leur version et leur taille. De là, vous pouvez {restore} toute sauvegarde complète (fichiers + base de données — une copie de sécurité de la base de données actuelle est d’abord réalisée) ou {delete} les anciennes.',
'Upd_Restore_Verb' => 'restaurer',
'Upd_Delete_Verb' => 'supprimer',
'Upd_Guide_Backups_Retention' => 'Utilisez {keep} pour choisir le nombre de sauvegardes conservées ; les plus anciennes sont supprimées automatiquement après chaque mise à jour réussie. La dernière sauvegarde complète restante ne peut jamais être supprimée — vous gardez toujours un moyen de revenir en arrière.',
'Upd_Guide_Manual_Title' => '5. Mise à jour manuelle (méthode de secours)',
'Upd_Guide_Manual_Text' => 'Si vous préférez effectuer la mise à jour à la main, ou si l’outil de téléversement ne peut pas être utilisé sur votre serveur, suivez les instructions pas à pas de l’onglet {tab} de cette page.',
'Upd_Guide_Clear_Cache_First' => 'Si des pages semblent cassées ou vides après une mise à jour, videz d’abord le cache de votre navigateur — c’est presque toujours la cause.',
'Upd_Restore_Backup_Confirm' => 'Restaurer cette sauvegarde ? Les fichiers et la base de données actuels seront remplacés par la sauvegarde. Une copie de sécurité de la base de données actuelle est d’abord réalisée. (v{version} — {date})',
'Woo_Guide_Lead' => 'Comment une boutique WooCommerce reste synchronisée avec l’ERP. Les lignes cron ci-dessous sont générées pour ce serveur et peuvent donc y être copiées telles quelles.',
'Woo_Guide_Ways_Note' => 'Contrairement à Shopify, WooCommerce n’envoie rien de lui-même à l’ERP — il n’y a pas de récepteur de webhooks ici, donc tout ce qui {in} arrive selon la planification. Seul le stock {out} peut partir immédiatement.',
'Woo_In' => 'entre',
'Woo_Out' => 'sortant',
'Woo_Guide_Both_Ways_Title' => 'Les deux modes nécessitent d’abord ceci',
'Woo_Api_Keys' => 'Clés API',
'Woo_Guide_Api_Keys_Text' => '{path}, autorisation {perm}. Copiez la clé client (consumer key) et le secret dans l’onglet {settings}, ainsi que l’URL de la boutique — l’adresse de votre site sans barre oblique finale, par ex. {example}.',
'Woo_Credentials_Saved' => 'identifiants enregistrés',
'Woo_Not_Configured_Yet' => 'pas encore configuré',
'Woo_Guide_Wp_App_Password_Title' => 'Mot de passe d’application WordPress (facultatif)',
'Woo_Guide_Wp_App_Password_Text' => 'Utilisé uniquement pour les images des produits. L’API WooCommerce transfère les produits, le stock, les catégories, les marques, les clients et les commandes ; l’API WordPress sert à rechercher dans la médiathèque et à téléverser une image qui n’y figure pas encore.',
'Woo_Guide_Wp_App_Password_Note' => 'Utilisez un utilisateur WordPress pouvant gérer les médias, et créez le mot de passe dans {path}. Si vous laissez les deux champs vides, tout se synchronise quand même — seul l’ajout des images est ignoré.',
'Woo_Guide_Pick_Way_Title' => 'Choisissez ensuite le mode de synchronisation',
'Woo_Right_Away' => 'Immédiatement',
'Woo_Stock_Live' => 'stock en temps réel',
'Woo_Stock_Not_Live' => 'stock pas en temps réel',
'Woo_Guide_Realtime_Lead' => 'Un seul sens : le stock et les produits qui sortent de l’ERP. Les commandes et les modifications de produits effectuées dans WooCommerce arrivent toujours selon la planification — voir l’autre onglet.',
'Woo_Push_Stock_On_Change' => 'Envoyer le stock dès qu’il change',
'Woo_Setting_People_Miss' => 'C’est le paramètre que l’on oublie souvent',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Une vente POS {not} WooCommerce d’elle-même. Si cette option est désactivée, la boutique ne l’apprend qu’à la prochaine synchronisation du stock — une heure par défaut — et pendant ce délai, elle peut vendre une unité déjà vendue en caisse.',
'Woo_Does_Not' => 'n’atteint pas',
'Woo_Guide_Tick_Instant' => 'Cochez {option} dans l’onglet {settings}. C’est toute la configuration — ni worker, ni cron. Chaque vente, retour, ajustement, transfert et achat réceptionné envoie alors uniquement les produits concernés, juste après l’enregistrement de la vente, et une vente de vingt lignes ne coûte qu’un envoi, pas vingt. La caisse ne l’attend jamais.',
'Woo_Currently' => 'Actuellement :',
'Woo_Instant_On_Text' => 'activé — stock envoyé à chaque changement',
'Woo_Instant_Off_Text' => 'désactivé — stock uniquement selon la planification',
'Woo_Guide_Instant_Note' => 'Seuls les produits déjà liés à WooCommerce sont envoyés — un produit jamais synchronisé n’a rien à corriger dans la boutique. Les produits variables passent par leur produit parent, et un combo est renvoyé dès que l’un de ses composants bouge. Les opérations en masse (suppression d’un produit, réinitialisation d’un entrepôt) écrivent le stock sans déclencher d’événement, ce qui est une raison de conserver aussi la synchronisation horaire du stock.',
'Woo_Push_Products_On_Save' => 'Envoyer les produits dès leur enregistrement',
'Woo_Guide_Tick_Auto_Products' => 'Cochez {option} dans l’onglet {settings} : un produit créé, modifié ou dupliqué dans Stocky est envoyé à WooCommerce juste après son enregistrement — détails, prix, variantes et images, puis son stock. Un nouveau produit est créé immédiatement dans la boutique au lieu d’attendre la synchronisation nocturne des produits.',
'Woo_On' => 'activé',
'Woo_Off' => 'désactivé',
'Woo_Guide_Bulk_Imports_Note' => 'Les importations en masse ne sont pas envoyées une par une — lancez une synchronisation des produits après une importation. Synchronisez d’abord les catégories et les marques, afin qu’un produit envoyé arrive dans la bonne catégorie.',
'Woo_Nothing_Else_To_Install' => 'Rien d’autre à installer',
'Woo_Guide_Same_Process' => 'Ni worker de file d’attente, ni entrée cron. L’envoi s’exécute dans le même processus que celui qui a traité la vente, {after} le renvoi de la réponse, de sorte que la caisse n’attend jamais WooCommerce. Les envois ne se chevauchent jamais : les changements effectués pendant un envoi attendent sa fin et partent juste après.',
'Woo_After' => 'après',
'Woo_Guide_Shop_Stops_Answering' => 'Une boutique qui ne répond plus est abandonnée au bout de huit secondes, et les envois sont suspendus pendant cinq minutes afin que chaque vente ne l’attende pas à nouveau ; les changements survenus entre-temps partent avec le premier envoi après la pause, et la synchronisation horaire du stock rattrape de toute façon le retard. Chaque pause est enregistrée dans l’onglet Journaux.',
'Woo_Guide_Artisan_Exception' => 'Une exception : une modification de stock effectuée par une commande artisan n’a pas de réponse à attendre ; elle est donc placée dans la file {queue}. Pour que ces envois partent eux aussi rapidement, videz cette file :',
'Woo_Cron_Line_Copied' => 'Ligne cron copiée',
'Woo_Command_Copied' => 'Commande copiée',
'Woo_Guide_Not_Woo_Queue' => 'Volontairement pas la file {queue} : celle-ci transporte les lots de catalogue qui durent des heures, et un envoi instantané placé derrière l’un d’eux ne serait plus instantané.',
'Woo_On_A_Schedule' => 'Selon une planification',
'Woo_Guide_Scheduled_Lead' => 'Tout est revérifié régulièrement, dans les deux sens. C’est ainsi que les commandes arrivent dans l’ERP, qu’un catalogue est publié et que tout ce que la voie rapide a manqué est corrigé. Chaque tâche a sa propre entrée cron : vous n’exécutez que ce que vous voulez.',
'Woo_Guide_Sync_Drains_Queue' => '{command} vide sa propre file pendant son exécution ; ces lignes ne nécessitent donc aucun worker séparé. Sous Windows, utilisez le Planificateur de tâches avec le programme {program} et les mêmes arguments, démarré dans {path}.',
'Woo_Or_No_Cron' => 'Ou pas de cron du tout',
'Woo_Guide_No_Cron_Text' => 'Chaque onglet ici synchronise à la demande, et une synchronisation manuelle traite ses propres lots tant que la page est ouverte — une petite boutique peut donc fonctionner sans aucune entrée cron. Ce que vous perdez, c’est tout ce qui se passe quand personne ne regarde : les commandes n’arrivent que lorsque quelqu’un appuie sur le bouton.',
'Woo_Commands_Worth_Knowing' => 'Commandes utiles',
'Woo_Worth_Knowing' => 'Bon à savoir',
'Woo_Guide_Changing_Url_Clears' => 'Changer l’URL de la boutique ou les clés API efface toutes les correspondances — produits, catégories, marques et clients sont tous resynchronisés vers la nouvelle boutique.',
'Woo_Guide_Keep_Skus' => 'Gardez des SKU cohérents entre Stocky et WooCommerce : c’est ce qui évite les doublons et rend la reliaison sûre.',
'Woo_Guide_Stock_Total' => 'Le stock publié sur Woo est le {total}, et non le chiffre d’un seul entrepôt.',
'Woo_Total_Across_Warehouses' => 'total de tous les entrepôts',
'Woo_Guide_Full_Reference' => 'La référence complète — chaque périmètre, le fonctionnement de la file d’attente et une liste de dépannage — se trouve dans {file}.',
'Woo_Way_Covers' => 'Couvre',
'Woo_Way_Covers_Realtime' => 'Uniquement le stock qui sort de l’ERP — une vente POS, un retour, un ajustement, un achat réceptionné',
