'Woo_No_Shop_Connected' => 'Aucune boutique n’est encore connectée',
'Woo_No_Shop_Connected_Desc' => 'Tout ce qui suit reste valable — saisissez l’URL de la boutique et les clés API sur la page des paramètres WooCommerce, puis revenez ici.',
'Woo_Wp_Username' => 'Nom d’utilisateur WordPress',
'Woo_Wp_App_Password' => 'Mot de passe d’application WordPress',
'Woo_Settings_Instant_Hint' => 'Une vente, un retour ou un ajustement envoie le stock des seuls produits concernés dès son enregistrement ; la boutique est ainsi à jour en quelques secondes au lieu d’attendre la prochaine synchronisation horaire du stock. Rien d’autre à installer — l’envoi s’exécute une fois la vente traitée, donc la caisse n’attend jamais WooCommerce. Plus de détails dans l’onglet {guide}.',
'Woo_Settings_Instant_Off_Alert' => 'Si cette option reste désactivée, une vente POS n’atteint WooCommerce qu’à la prochaine synchronisation du stock — jusqu’à une heure plus tard.',
'Woo_Settings_Auto_Products_Hint' => 'Un produit créé, modifié ou dupliqué dans Stocky est envoyé à WooCommerce juste après son enregistrement — détails, prix, variantes, images, puis son stock — au lieu d’attendre une synchronisation des produits. Les importations en masse ne sont pas envoyées ; lancez une synchronisation des produits après une importation.',
'Woo_Sync_Tuning' => 'Réglage de la synchronisation',
'Woo_Sync_Tuning_Intro' => 'Les valeurs par défaut conviennent à la plupart des boutiques. Ne les modifiez que si la synchronisation est lente ou expire sur votre hébergement. Chaque valeur est limitée à une plage sûre, et vider un champ rétablit sa valeur par défaut.',
'Woo_Setting_This_Up' => 'Configuration',
'Woo_Setting_This_Up_Text' => 'L’obtention des clés API, l’utilité du mot de passe d’application WordPress, les entrées cron des synchronisations planifiées et la façon de faire parvenir le stock à la boutique dès qu’il change — tout cela, avec les lignes cron propres à ce serveur prêtes à copier, se trouve dans l’onglet Guide. Une seule copie, pour qu’elle ne puisse pas s’écarter de ce que fait réellement le module.',
