'Telegram_G_A_Title' => 'Immédiatement — rien à installer',
'Telegram_G_A_Body' => 'Une vente, un achat, un paiement ou une dépense enregistré dans Stocky — au POS ou dans l’administration — est envoyé à Telegram {after} son enregistrement, dans la même requête. Ni entrée cron, ni worker de file d’attente, et le caissier n’attend jamais Telegram : la vente a déjà été traitée lorsque le message part.',
'Telegram_G_Right_After' => 'juste après',
'Telegram_G_B_Title' => 'L’entrée cron — pour les nouvelles tentatives et les événements en arrière-plan',
'Telegram_G_B_Body' => 'Deux types de messages attendent plutôt dans la file propre à Telegram : un envoi qui a échoué (Telegram momentanément injoignable), qui est retenté jusqu’à trois fois de plus au cours des minutes suivantes ; et les événements déclenchés hors de l’administration — commandes importées depuis WooCommerce ou Shopify, commandes artisan. Cette entrée cron les envoie, et rien d’autre :',
'Telegram_G_Cron_Note' => 'Toutes les minutes, c’est le bon rythme : une exécution sans rien en attente se termine aussitôt. Sur cPanel, cela se configure dans {cronJobs} — utilisez le chemin complet vers PHP 8.2+ si {php} est plus ancien. Sous Windows, utilisez le Planificateur de tâches avec le programme {program}, les arguments {args}, démarré dans {path}.',
