'Xero_Org_Connected' => 'Organisation Xero connectée.',
'Jumia_Hero_Title' => 'Synchronisation de la marketplace Jumia',
'Jumia_Hero_Desc' => 'Envoyez les prix et le stock vers vos fiches Jumia Seller Center et importez les commandes de la marketplace comme ventes.',
'Jumia_Api_Url_Label' => 'URL de l’API (point d’accès Seller Center de votre pays)',
