'Jumia_Prices_Stock' => 'Prix et stock',
'Jumia_Push_Prices_Stock_Title' => 'Envoyer les prix et le stock vers Jumia',
'Jumia_Push_Prices_Stock_Desc' => 'Envoie le prix et la quantité actuels de chaque produit (et variante) dont le SKU correspond au {sku} de la fiche Jumia. Les mises à jour sont soumises sous forme de flux Seller Center et appliquées de manière asynchrone — l’ID du flux est enregistré dans l’onglet Journaux, et les rejets par article apparaissent dans l’écran d’état des flux de Seller Center.',
'Jumia_Push_Prices_Stock' => 'Envoyer les prix et le stock',
'Jumia_Pull_Orders_Desc' => 'Importe les commandes de la marketplace comme ventes (références du type {ref}), associées à vos produits par Seller SKU. Les commandes déjà importées et annulées sont ignorées, vous pouvez donc les récupérer régulièrement sans risque. Les paiements ne sont marqués payés que pour les commandes livrées (Jumia fonctionne majoritairement en paiement à la livraison).',
'Jumia_Guide_1' => 'Dans Jumia {sellerCenter}, ouvrez {menu} et générez une clé API.',
'Jumia_Guide_2' => 'Saisissez l’URL de l’API de votre pays (par ex. {ng} pour le Nigeria, {ke} pour le Kenya, {eg} pour l’Égypte), l’e-mail de votre compte Seller Center et la clé — puis lancez {test}.',
'Jumia_Guide_3' => 'Assurez-vous que le {sku} de chaque fiche Jumia est identique au code produit Stocky — c’est l’identifiant utilisé à la fois pour l’envoi du stock et l’association des commandes.',
'Jumia_Guide_4' => 'Envoyez les prix et le stock après chaque modification d’inventaire ; récupérez les commandes régulièrement (cette API Jumia ne propose pas de webhooks).',
'Jumia_Guide_5' => 'La création de nouvelles fiches se fait toujours dans Seller Center — Jumia exige des attributs propres à chaque catégorie et une vérification des images que seul son portail gère correctement.',
'Mailchimp_Hero_Title' => 'Synchronisation d’audience Mailchimp',
