'Mailchimp_Auto_Sync_Customers' => 'Synchroniser automatiquement les nouveaux clients dès leur création',
'Mailchimp_With_Email' => 'Avec un e-mail',
'Mailchimp_Push_Desc' => 'Ajoute ou met à jour dans l’audience sélectionnée chaque client disposant d’une adresse e-mail (nom et téléphone inclus). Les membres existants conservent leur statut d’abonnement — personne ne se retrouve réabonné après s’être désabonné. Les clients sans e-mail sont exclus.',
'Mailchimp_Double_Optin_Off_Title' => 'Le double opt-in est désactivé',
