'Mailchimp_Guide_1' => 'Dans Mailchimp, ouvrez {menu} et créez une clé (elle se termine par {suffix} — ce suffixe correspond à votre datacenter).',
'Mailchimp_Guide_2' => 'Collez la clé ici, enregistrez, puis cliquez sur {load} et choisissez l’audience à alimenter.',
