'Shopify_Hook_Note_Register' => 'L’enregistrement crée les abonnements dans Shopify et les fait pointer automatiquement vers cette adresse. Ne l’ajoutez pas manuellement dans Shopify → Settings → Notifications → Webhooks : ceux-ci sont signés avec un autre secret et chaque envoi serait refusé.',
'Shopify_Hook_Verified_Client' => 'Les envois sont vérifiés avec le secret client de l’application, déjà enregistré.',
'Shopify_Hook_Signature_Required' => 'Les envois sans signature valide sont refusés : le secret doit donc être défini pour que les webhooks aient un effet.',
'Shopify_Hook_Retries' => 'Shopify réessaie jusqu’à obtenir une réponse 2xx, et chaque envoi n’est enregistré qu’une fois — un événement répété est sans effet et ne crée pas de commande en double.',
'Shopify_No_Signing_Secret' => 'Aucun secret de signature enregistré',
'Shopify_No_Signing_Secret_Desc' => 'Les abonnements peuvent être créés sans secret, mais chaque envoi sera refusé tant que la clé secrète API de l’application n’est pas enregistrée sur cette boutique (le secret client d’une application Dev Dashboard suffit déjà).',
'Shopify_Register_In_Shopify' => 'Enregistrer dans Shopify',
'Shopify_Refresh_List' => 'Actualiser la liste',
'Shopify_Prune_Confirm' => 'Supprimer nos abonnements pour les entités que cette boutique ne synchronise plus ?',
'Shopify_Tidy_Up' => 'Faire le ménage',
'Shopify_Topics_Subscribed' => '{mine} sur {total} sujets abonnés',
'Shopify_Topics_Handled' => 'Sujets gérés par cet ERP :',
'Shopify_Another_App' => 'une autre application',
'Shopify_Delete_Sub_Confirm' => 'Supprimer cet abonnement dans Shopify ?',
'Shopify_Replay' => 'Rejouer',
'Shopify_Setup_Guide' => 'Guide de configuration',
'Shopify_No_Errors' => 'Aucune erreur enregistrée',
'Shopify_All_Logs_Store' => 'Tous les journaux de cette boutique',
'Shopify_Topic' => 'Sujet',
'Shopify_Step' => 'Étape',
'Shopify_Interval' => 'Intervalle',
'Shopify_Last_Run' => 'Dernière exécution',
'Shopify_Delivers_To' => 'Envoie à',
'Shopify_Replayed' => 'Rejoué',
'Shopify_Replay_Failed' => 'Échec de la relecture',
'Shopify_URL_Copied' => 'URL copiée',
'Shopify_Topic_Hint_Refresh' => 'Cliquez sur « Actualiser la liste » pour vérifier si cette boutique est abonnée',
'Shopify_Topic_Not_Needed' => 'Inutile — son entité est désactivée pour cette boutique',
'Shopify_Not_Subscribed' => 'Pas encore abonné',
'Shopify_Subscribed' => 'Abonné',
'Shopify_Could_Not_Read_Hooks' => 'Impossible de lire les webhooks de cette boutique',
'Shopify_Hooks_Partial' => '{created} créés, {failed} en échec — consultez les journaux',
'Shopify_Subs_Created' => '{n} abonnement(s) créé(s)',
'Shopify_Subs_Created_Removed' => '{n} abonnement(s) créé(s), {removed} supprimé(s)',
'Shopify_Already_Subscribed' => 'Déjà abonné à tout ce dont cette boutique a besoin',
'Shopify_Could_Not_Register' => 'Impossible d’enregistrer les webhooks',
'Shopify_Sub_Removed' => 'Abonnement supprimé',
'Shopify_Could_Not_Remove_Sub' => 'Impossible de supprimer cet abonnement',
'Shopify_Could_Not_Load_Store' => 'Impossible de charger cette boutique',
'Shopify_G_Lead_Store' => 'Ce dont cette boutique a besoin pour rester synchronisée. Tout ce qui figure ici est propre à cette boutique — les chemins et les id sont réels, les commandes peuvent donc être copiées telles quelles sur le serveur.',
'Shopify_G_Lead_Generic' => 'Comment une boutique Shopify reste synchronisée avec l’ERP. Sélectionnez une boutique ci-dessus pour voir son état, ou lisez ce guide tel quel — la ligne cron et l’URL du webhook sont les mêmes quelle que soit la boutique connectée.',
'Shopify_G_Ways_Note' => 'La plupart des boutiques utilisent les deux : la première maintient la boutique à jour minute par minute, la seconde rattrape tout ce que la première a manqué — un webhook jamais arrivé, une modification faite directement dans l’administration Shopify, une nuit où le site était hors ligne.',
'Shopify_G_Both_Need' => 'Les deux méthodes nécessitent d’abord ceci',
'Shopify_G_Credentials' => 'Identifiants Shopify',
'Shopify_G_Cred_Intro' => 'Depuis janvier 2026, Shopify ne permet plus de créer des applications personnalisées dans l’administration ; il existe donc deux types de connexion :',
'Shopify_G_Cred_DevDash' => '{app} (toute boutique connectée aujourd’hui) — {path}. Accordez les scopes Admin API correspondant à ce que cette boutique synchronise, installez l’application sur la boutique, puis copiez le {clientId} et le {clientSecret} depuis la page Settings de l’application dans {where}. L’ERP les échange lui-même contre un jeton d’accès et le renouvelle avant son expiration toutes les 24 heures. Le secret client signe aussi les webhooks, rien d’autre n’est donc nécessaire. L’application et la boutique doivent appartenir à la même organisation Shopify.',
'Shopify_G_Dev_Dashboard_App' => 'Application Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (créée dans l’administration avant 2026) — continue de fonctionner sans changement avec son {token} ({prefix}) et sa {secret} comme secret de signature des webhooks. Ce n’est pas la même valeur que le jeton, et les inverser est la raison habituelle du refus des webhooks.',
'Shopify_G_Legacy_App' => 'Ancienne application personnalisée',
'Shopify_G_API_Secret_Key' => 'Clé secrète API',
'Shopify_G_Stored' => 'enregistré',
'Shopify_G_Missing_Refused' => 'manquant — les envois seront refusés',
'Shopify_G_Where_Data_Desc' => '{path} L’entrepôt ERP dont cette boutique vend le stock, et l’emplacement Shopify dans lequel ce stock est écrit. La synchronisation de l’inventaire et l’import des commandes refusent tous deux de s’exécuter sans eux.',
'Shopify_G_Currently' => 'Actuellement : entrepôt {warehouse}, emplacement {location}',
'Shopify_G_Not_Set_Lower' => 'non défini',
'Shopify_G_Ready' => 'prêt',
'Shopify_G_Incomplete' => 'incomplet',
'Shopify_G_Manual_Syncs' => 'Synchronisations lancées manuellement',
'Shopify_G_Manual_Desc' => 'Une synchronisation lancée depuis le {centre} répond immédiatement et s’exécute en arrière-plan, par courtes tranches qui reprennent chacune là où la précédente s’est arrêtée. Un gros catalogue n’est jamais interrompu en cours de route par un hébergement qui coupe les requêtes web longues (LiteSpeed, nginx, un répartiteur de charge), et fermer la page ne l’arrête pas. Le worker correspondant nécessite une ligne cron supplémentaire :',
'Shopify_G_Cron_Copied' => 'Ligne cron copiée',
'Shopify_G_Manual_Note' => 'Sans elle, une synchronisation se termine quand même, mais uniquement tant que la page du Centre de synchronisation reste ouverte : si aucun worker ne prend en charge une exécution en quelques secondes, la page la poursuit elle-même, une courte requête à la fois. Sous Windows, utilisez le Planificateur de tâches toutes les minutes : programme {program}, arguments {args}, démarrer dans {dir}.',
'Shopify_G_Then_Pick' => 'Choisissez ensuite le mode de synchronisation',
'Shopify_G_Right_Away' => 'Immédiatement',
'Shopify_G_Stock_Live' => 'stock en direct',
'Shopify_G_Stock_Not_Live' => 'stock non en direct',
'Shopify_G_Realtime_Lead' => 'Chaque modification est envoyée au moment où elle se produit, en quelques secondes. Deux volets, avec des interrupteurs distincts : les {webhooks} font entrer les événements de la boutique, et l’{push} fait sortir le stock.',
'Shopify_G_Webhooks_Lower' => 'webhooks',
'Shopify_G_Instant_Push_Lower' => 'envoi instantané du stock',
'Shopify_G_Webhooks_In' => 'Webhooks — la boutique → l’ERP',
'Shopify_G_Webhooks_Desc' => 'Les commandes, les changements de statut de commande, ainsi que les modifications de produits, de clients et de stock effectuées dans Shopify. Ouvrez la boutique et cliquez sur {button} dans son {tab} — vous pouvez cliquer deux fois sans risque. Shopify envoie à :',
'Shopify_G_Webhooks_Tab' => 'onglet Webhooks',
'Shopify_G_Webhooks_Note' => 'L’adresse doit être accessible depuis Internet en HTTPS — Shopify n’envoie rien vers {localhost} ni vers un domaine {test}. Chaque envoi n’est enregistré qu’une fois, les nouvelles tentatives de Shopify ne peuvent donc pas créer de commande en double, et un envoi échoué peut être rejoué. Les envois sont refusés tant que le secret de signature de l’étape 1 n’est pas enregistré.',
'Shopify_G_Instant_Out' => 'Envoi instantané du stock — l’ERP → la boutique',
'Shopify_G_Setting_Missed' => 'C’est le paramètre que l’on oublie',
'Shopify_G_Pos_Not_Auto' => 'Une vente POS n’atteint {not} Shopify d’elle-même. Si l’option est désactivée, la boutique n’en est informée qu’à la prochaine étape d’envoi de l’inventaire — et dans cet intervalle, elle peut vendre une unité que vous avez déjà vendue en caisse.',
'Shopify_G_Not' => 'pas',
'Shopify_G_Tick_Push' => 'Cochez {setting} dans {where}. C’est toute la configuration — ni worker, ni cron. Chaque vente, retour et ajustement envoie alors le stock des seuls produits concernés, juste après l’enregistrement de la vente, et une vente de vingt lignes ne coûte qu’un envoi, pas vingt. La caisse ne l’attend jamais.',
'Shopify_G_This_Store' => 'Cette boutique :',
'Shopify_G_Push_On' => 'activé — stock envoyé à chaque modification',
'Shopify_G_Push_Off' => 'désactivé — stock uniquement selon la planification',
'Shopify_G_Push_Note' => 'Seuls les produits déjà associés à Shopify, et seuls les mouvements dans l’entrepôt de cette boutique, sont envoyés. Les opérations en masse — supprimer un produit, réinitialiser un entrepôt — écrivent le stock sans déclencher d’événement, ce qui est une raison de conserver aussi l’étape d’inventaire planifiée.',
'Shopify_G_Nothing_Install' => 'Rien d’autre à installer',
'Shopify_G_No_Worker_Note' => 'Aucun des deux volets ne nécessite de worker de file d’attente ni d’entrée cron. Un webhook entrant est traité dans la requête émise par Shopify ; un envoi de stock sortant s’exécute dans le même processus que celui qui a servi la vente, {after} le renvoi de la réponse — la caisse n’attend donc jamais Shopify, et une boutique qui ne répond plus est abandonnée au bout de dix secondes et laissée au prochain envoi d’inventaire planifié.',
'Shopify_G_After' => 'après',
'Shopify_G_Artisan_Note' => 'Une exception : une modification de stock effectuée par une commande artisan n’a pas de réponse après laquelle s’exécuter, elle est donc mise en file d’attente sur {queue}. Si vous souhaitez que ces envois partent aussi rapidement, traitez cette file :',
'Shopify_G_On_Schedule' => 'Selon une planification',
'Shopify_G_On_Lower' => 'activé',
'Shopify_G_Off_Lower' => 'désactivé',
'Shopify_G_Scheduled_Lead' => 'Tout est revérifié régulièrement, dans les deux sens. C’est plus lent que le temps réel, mais c’est ce qui envoie le stock pour les boutiques qui n’utilisent pas l’envoi instantané, ce qui rattrape un webhook manqué, et le seul moyen de transférer un catalogue entier.',
'Shopify_G_Cron_Entry' => 'L’entrée cron',
'Shopify_G_Cron_Entry_Desc' => 'Rien de planifié ne s’exécute sans elle. Une seule ligne, pour ce module uniquement — ajoutez-la à côté de tout ce que vous avez choisi de planifier :',
'Shopify_G_Cron_Note' => 'Toutes les cinq minutes est la résolution la plus fine qu’un plan peut utiliser, car cinq minutes est l’intervalle d’étape le plus court. Une entrée moins fréquente devient simplement le plancher — avec {example}, une étape réglée sur 5 minutes s’exécute toutes les 15. Sous Windows, utilisez le Planificateur de tâches : programme {program}, arguments {args}, démarrer dans {dir}.',
'Shopify_G_Switch_On_Plan' => 'Activez-la et choisissez le plan',
'Shopify_G_Plan_Desc' => '{where} L’interrupteur détermine si le cron peut agir ; le plan détermine ce qu’il fait. Une {step} correspond à une entité dans un sens, avec son propre intervalle — {first}, {second}. L’intervalle par défaut est utilisé par toute étape dont le champ reste vide.',
'Shopify_G_Step_Lower' => 'étape',
'Shopify_G_Plan_Note' => 'Laissez le plan vide et la boutique récupère les commandes et envoie le stock à l’intervalle par défaut, ce que souhaitent la plupart des boutiques. Les commandes sont uniquement récupérées : c’est sur Shopify que le client les passe.',
'Shopify_G_Schedule_On' => 'planification activée',
'Shopify_G_Schedule_Off' => 'planification désactivée — manuel uniquement',
'Shopify_G_When_Step_Runs' => 'Quand une étape s’exécute réellement',
'Shopify_G_When_Note' => 'Une étape est à exécuter lorsque cette même étape a {started} pour la dernière fois il y a plus longtemps que son intervalle, d’après l’historique des exécutions. Ainsi, une synchronisation lancée manuellement repousse la prochaine synchronisation automatique, et une étape qui échoue sans cesse est relancée selon son intervalle plutôt qu’à chaque tick. La Vue d’ensemble de la boutique affiche pour chaque étape sa dernière exécution, sa prochaine échéance et, le cas échéant, la raison de son blocage. Lancez le premier envoi du catalogue manuellement — avec {dryRun} d’abord — avant de le planifier.',
'Shopify_G_Started_Lower' => 'démarré',
'Shopify_G_Where_Setting' => 'Où se trouve chaque paramètre',
'Shopify_G_Where_Setting_Note' => 'Tous ces paramètres se trouvent sur une boutique existante : {path}, puis le crayon (ou {edit} sur la page de la boutique).',
'Shopify_G_Product_Images' => 'Images des produits',
'Shopify_G_Img_1' => 'Les images partent avec le produit lors d’un {push} — l’image principale d’abord, puis la galerie, puis une par variante qui possède la sienne, jusqu’à cinquante.',
'Shopify_G_Products_Push' => 'envoi des produits',
'Shopify_G_Img_2' => 'L’image d’une variante est téléversée avec le produit puis {assigned}, ce qui correspond au modèle de Shopify : une variante pointe vers l’une des images du produit. Une variante qui réutilise l’image principale ne la téléverse pas deux fois.',
'Shopify_G_Assigned' => 'attribuée à cette variante',
'Shopify_G_Img_3' => 'Une image stockée sous forme de fichier est {uploaded} vers Shopify, et non liée ; cela fonctionne donc même si cette installation n’est pas accessible depuis Internet. Une image ajoutée sous forme de lien collé est transmise à Shopify sous cette URL, qui doit être publiquement accessible.',
'Shopify_G_Uploaded' => 'téléversée',
'Shopify_G_Img_4' => 'Elles ne sont renvoyées que lorsqu’elles changent réellement — un envoi qui ne modifie qu’un prix ne touche pas aux images de la boutique, car les envoyer remplace l’ensemble.',
'Shopify_G_Img_5' => 'Supprimer une image dans l’ERP ne la supprime {not} dans Shopify. Supprimez-la là-bas aussi, sinon la boutique continue de l’afficher.',
'Shopify_G_Commands' => 'Commandes utiles',
'Shopify_G_Command_Copied' => 'Commande copiée',
'Shopify_G_Foot' => 'Chaque synchronisation écrit dans {logs}, et la Vue d’ensemble de chaque boutique indique quand chaque étape s’est exécutée pour la dernière fois, quand elle est prévue ensuite et ce qui la bloque le cas échéant. C’est là qu’il faut regarder en premier lorsqu’une synchronisation n’a pas fait ce que vous attendiez.',
'Shopify_G_Covers' => 'Couvre',
'Shopify_G_Covers_Rt' => 'Les commandes et modifications effectuées dans Shopify ; le stock sortant de l’ERP (une vente POS, un retour, un ajustement)',
'Shopify_G_Covers_Sch' => 'Tout, dans les deux sens — y compris les envois de catalogue et tout ce que la voie rapide a manqué',
'Shopify_G_Speed' => 'Rapidité',
'Shopify_G_Speed_Rt' => 'Quelques secondes',
'Shopify_G_Speed_Sch' => 'L’intervalle de l’étape (de 5 minutes à 7 jours)',
'Shopify_G_Needs' => 'Prérequis',
'Shopify_G_Needs_Rt' => 'Une adresse HTTPS publique et le secret de signature pour les webhooks entrants. Le stock sortant ne nécessite rien',
'Shopify_G_Needs_Sch' => 'Une entrée cron exécutant {cmd}',
'Shopify_G_Switched_On_At' => 'S’active dans',
'Shopify_G_On_Sch' => '{path}, plus le plan',
'Shopify_G_Scope_Orders' => '{scope} ({extra} pour les commandes de plus de 60 jours)',
'Shopify_G_Admin_Scopes' => 'Scopes Admin API',
'Shopify_G_Setting' => 'Paramètre',
'Shopify_G_Tab_In_Edit' => 'Onglet dans Modifier la boutique',
'Shopify_G_Set_Credentials' => 'ID client + secret ou jeton d’accès, secret de signature, version de l’API',
'Shopify_G_Set_Credentials_What' => 'Les identifiants de l’application Shopify (Dev Dashboard ou ancienne application personnalisée).',
'Shopify_G_Set_Targets' => 'Entrepôt ERP, emplacement Shopify',
'Shopify_G_Set_Targets_What' => 'Quel stock cette boutique vend, et où les commandes sont enregistrées.',
'Shopify_G_Set_Price_What' => 'Prix de détail, de gros ou minimum.',
'Shopify_G_Set_Create_Missing' => 'Créer les produits / clients manquants',
'Shopify_G_Set_Create_Missing_What' => 'Si une récupération peut créer dans l’ERP les enregistrements qu’elle ne parvient pas à associer.',
'Shopify_G_Set_Entities' => 'Quelles entités sont synchronisées',
'Shopify_G_Set_Entities_What' => 'Désactivé ici signifie désactivé partout — manuel, planifié et webhook.',
'Shopify_G_Set_Scheduler_What' => 'L’interrupteur du planificateur.',
'Shopify_G_Set_Push_What' => 'Envoi instantané du stock, déclenché par une vente ou un ajustement.',
'Shopify_G_Set_Plan' => 'Intervalle par défaut et plan des étapes',
'Shopify_G_Set_Plan_What' => 'Ce qui s’exécute automatiquement, dans quel sens et à quelle fréquence.',
'Shopify_G_Cmd_List' => 'Toutes les boutiques : ce qui s’exécuterait, et quand. Ne modifie rien.',
'Shopify_G_Cmd_Force' => 'Le plan complet d’une boutique maintenant, sans tenir compte de l’horloge.',
'Shopify_G_Cmd_First_Push' => 'Premier envoi du catalogue : uniquement les produits pas encore liés.',
'Shopify_G_Cmd_Backfill' => 'Rattraper les commandes à partir d’une date.',
'Shopify_G_Cmd_Dry' => 'Tout parcourir et générer un rapport, sans rien écrire nulle part.',
'StoreAdm_Banner_Recommended_Size' => 'Recommandé : {w} × {h} ({ratio})',
'StoreAdm_Banner_Uploaded_Size' => 'Téléversé : {w} × {h} ({ratio})',
'StoreAdm_Banner_Top_Both' => 'Haut (gauche/droite)',
'StoreAdm_Banner_Center_Both' => 'Centre (gauche/droite)',
'StoreAdm_Banner_Footer_Both' => 'Pied de page (gauche/droite)',
'StoreAdm_Banner_Retina_Tip' => 'Astuce : utilisez le format 2x pour les écrans Retina (par ex. {size}).',
'StoreAdm_Banner_Top_Left' => 'Haut — Gauche',
'StoreAdm_Banner_Top_Right' => 'Haut — Droite',
'StoreAdm_Banner_Center_Left' => 'Centre — Gauche',
'StoreAdm_Banner_Center_Right' => 'Centre — Droite',
'StoreAdm_Banner_Footer_Left' => 'Pied de page — Gauche',
'StoreAdm_Banner_Footer_Right' => 'Pied de page — Droite',
'StoreAdm_NA' => 'N/D',
'StoreAdm_Eg' => 'par ex. {example}',
'StoreAdm_Stock_Required_Available' => '{name} : requis {need} — disponible {have}',
'StoreAdm_PG_Intro_Msg' => 'PayPal, Paystack, Flutterwave, Razorpay, bKash et SSLCommerz sont utilisés UNIQUEMENT par le paiement de la BOUTIQUE EN LIGNE.',
'StoreAdm_PG_Intro_Desc' => 'Les clés Stripe sont partagées globalement (l’administration et la boutique en ligne utilisent la même intégration Stripe). Chaque onglet active ou désactive son moyen de paiement pour le paiement de la boutique en ligne ; Paiements hors ligne regroupe les moyens de paiement réglés en dehors du système.',
'StoreAdm_PG_Used_By_Store_Only' => 'Utilisé uniquement par le paiement de la boutique en ligne',
'StoreAdm_PG_Gw_Key' => 'Clé {gw}',
'StoreAdm_PG_Gw_Secret' => 'Secret {gw}',
'StoreAdm_PG_Cards_Off' => 'Les paiements par carte sont désactivés',
'StoreAdm_PG_Cards_Off_Desc' => 'Vos clés sont conservées — le paiement de la boutique en ligne cesse simplement de proposer l’option carte jusqu’à ce que vous la réactiviez.',
'StoreAdm_PG_No_Stripe_Key' => 'Aucune clé Stripe enregistrée',
'StoreAdm_PG_No_Stripe_Key_Desc' => 'Saisissez votre clé et votre secret Stripe pour commencer à accepter les paiements par carte dans la boutique en ligne.',
'StoreAdm_PG_Gw_Client_Id' => 'ID client {gw}',
'StoreAdm_PG_Gw_Client_Secret' => 'Secret client {gw}',
'StoreAdm_PG_Sandbox' => 'Sandbox (mode test)',
'StoreAdm_PG_Sandbox_Paypal_Hint' => 'ACTIVÉ utilise {sandbox} avec des identifiants sandbox ; DÉSACTIVEZ pour débiter de vrais comptes sur {live}.',
'StoreAdm_PG_Gw_Webhook_Id_Opt' => 'ID de webhook {gw} (facultatif)',
'StoreAdm_PG_Paypal_Webhook_Hint' => 'Solution de secours pour les paiements dont la redirection du navigateur n’aboutit jamais, ainsi que pour les remboursements/rétrofacturations. Enregistrez sur {site} un webhook pointant vers l’URL ci-dessous (événements {events}) et collez ici son ID de webhook.',
'StoreAdm_PG_Webhook_Url' => 'URL du webhook :',
'StoreAdm_PG_Gw_Disabled' => '{gw} est désactivé',
'StoreAdm_PG_Paypal_Disabled_Desc' => 'Activez PayPal et saisissez l’ID client et le secret de votre application REST (depuis {site}) pour permettre aux clients de payer avec PayPal lors du paiement de la boutique en ligne.',
'StoreAdm_PG_Gw_Public_Key' => 'Clé publique {gw}',
'StoreAdm_PG_Gw_Secret_Key' => 'Clé secrète {gw}',
'StoreAdm_PG_Paystack_Test_Live' => 'Le mode test ou production dépend de la paire de clés : les clés {test} fonctionnent en mode test, les clés {live} débitent de vraies cartes — il n’y a pas d’interrupteur sandbox distinct.',
'StoreAdm_PG_Paystack_Webhook_Url' => 'URL du webhook (solution de secours facultative — à définir dans Settings → API Keys & Webhooks du tableau de bord Paystack ; les requêtes sont vérifiées par HMAC avec votre clé secrète) :',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'Activez Paystack et saisissez vos clés publique et secrète (depuis {site} → Settings → API Keys) pour accepter les cartes, les virements bancaires et le mobile money lors du paiement de la boutique en ligne.',
'StoreAdm_PG_Secret_Hash_Opt' => 'Secret Hash (webhooks, facultatif)',
'StoreAdm_PG_Flutterwave_Hash_Hint' => 'Le Secret Hash défini dans Settings → Webhooks du tableau de bord Flutterwave ; les webhooks entrants sont rejetés si leur en-tête {header} ne correspond pas.',
'StoreAdm_PG_Flutterwave_Info' => 'Utilise l’API Flutterwave v3 avec les clés classiques. Le mode test ou production dépend de la paire de clés ({keys} ou clés de production) — il n’y a pas d’interrupteur sandbox distinct. La devise de la boutique doit être activée sur votre compte Flutterwave.',
'StoreAdm_PG_Flutterwave_Webhook_Url' => 'URL du webhook (solution de secours facultative — à définir avec le Secret Hash ci-dessus dans le tableau de bord Flutterwave) :',
'StoreAdm_PG_Flutterwave_Disabled_Desc' => 'Activez Flutterwave et saisissez vos clés publique et secrète v3 (depuis {site} → Settings → API) pour accepter les cartes, le mobile money et les virements bancaires lors du paiement de la boutique en ligne.',
'StoreAdm_PG_Gw_Key_Id' => 'Key ID {gw}',
'StoreAdm_PG_Gw_Key_Secret' => 'Key Secret {gw}',
