'Cr_Guide_T_Statuses' => 'Statuts',
'Cr_Guide_Statuses_Note' => 'Les statuts ne font qu’avancer : une mise à jour tardive ne fait jamais reculer un colis. Un colis livré peut toutefois encore être signalé comme en retour ou retourné.',
'Cr_Guide_S_booked' => 'Le transporteur a la commande ; personne ne l’a encore collectée. Une réservation ne peut être annulée qu’à ce stade.',
'Cr_Guide_S_picked_up' => 'Le transporteur a collecté le colis.',
'Cr_Guide_S_in_transit' => 'En transit entre les centres, en douane ou en attente.',
'Cr_Guide_S_out_for_delivery' => 'Avec le livreur aujourd’hui.',
'Cr_Guide_S_failed_attempt' => 'Absent, refusé ou adresse erronée. Le transporteur réessaie ou le retourne.',
'Cr_Guide_S_delivered' => 'Remis au client. Un montant COD passe à « Encaissé par le transporteur ».',
'Cr_Guide_S_returning' => 'En cours de retour vers vous.',
'Cr_Guide_S_returned' => 'De retour chez vous : il attend dans « Retours à examiner », ou est remis en stock automatiquement.',
'Cr_Guide_S_cancelled' => 'La réservation a été annulée.',
'Cr_Guide_T_Booking' => 'Réservation des commandes',
'Cr_Guide_B_Booking' => '« Envoyer au transporteur » remplit le formulaire à partir de la vente : destinataire, adresse, montant restant dû en COD et poids des produits. Les transporteurs disposant de leur propre liste de villes affichent un sélecteur, et votre choix est mémorisé pour cette ville. Les agrégateurs, DHL, FedEx, UPS et Lalamove proposent « Comparer les tarifs » : choisissez un prix et « Réserver » l’achète. Plusieurs ventes peuvent être réservées en une seule fois depuis la liste des ventes.',
'Cr_Guide_T_Cod' => 'Paiement à la livraison',
'Cr_Guide_B_Cod' => 'Un colis COD passe de « Non encaissé » à « Encaissé par le transporteur » (à la livraison), puis à « Reversé ». Les transporteurs qui signalent leurs reversements gèrent eux-mêmes la dernière étape ; pour les autres, utilisez « Mettre à jour le COD ». Si un compte est choisi dans les paramètres des transporteurs, un reversement est enregistré comme paiement sur la vente. Les frais de transport peuvent être enregistrés comme dépense une fois le colis terminé.',
'Cr_Guide_T_Returns' => 'Colis retournés',
'Cr_Guide_B_Returns' => 'Par défaut, un colis retourné attend dans Expéditions transporteur, sous « Retours à examiner ». « Remettre en stock » crée un retour de vente pour toute la commande et remet les articles en stock ; « Ignorer » ne remet rien en stock, pour les colis endommagés ou perdus. Les paramètres des transporteurs permettent plutôt de remettre en stock automatiquement.',
'Cr_Guide_T_Customers' => 'Messages clients et page de suivi',
'Cr_Guide_B_Customers' => 'Les notifications clients des paramètres des transporteurs envoient un SMS, un e-mail ou un message WhatsApp aux statuts que vous cochez, une seule fois par colis, avec votre propre texte. La page de suivi de votre boutique en ligne permet aux clients de suivre un colis par numéro de suivi, ou par numéro de commande et téléphone. Les clients qui retournent souvent des colis reçoivent un badge de risque de retour lors de la réservation.',
'Cr_Guide_T_Labels' => 'Étiquettes',
'Cr_Guide_B_Labels' => '« Imprimer l’étiquette » fournit l’étiquette du transporteur lorsqu’il en émet une (un PDF, un lien ou une image), sinon une étiquette Stocky avec le code-barres de suivi et le montant à encaisser. Autorisez les fenêtres pop-up pour ce site afin d’imprimer. DHL, FedEx et UPS ne fournissent leur étiquette qu’une seule fois, lors de la réservation, et Stocky la conserve pour les réimpressions.',
'Cr_Guide_T_Faq' => 'Dépannage',
'Cr_Guide_Q_Test' => 'Le test de connexion échoue',
'Cr_Guide_A_Test' => 'Les clés de test vont avec le mode Test et les clés de production avec le mode Production ; elles sont différentes. Ouvrez les journaux des transporteurs et lisez la réponse du transporteur pour connaître la raison exacte.',
'Cr_Guide_Q_City' => 'Le transporteur refuse la ville ou l’adresse',
'Cr_Guide_A_City' => 'Choisissez la ville dans la liste des villes du transporteur du formulaire de réservation ; les transporteurs n’acceptent que leurs propres noms. Les transporteurs qui utilisent des adresses postales ont aussi besoin de la région, du code postal et du code pays à deux lettres.',
'Cr_Guide_Q_Webhook' => 'Les statuts ne changent pas d’eux-mêmes',
'Cr_Guide_A_Webhook' => 'Pour les transporteurs qui envoient des mises à jour, vérifiez que l’URL du webhook est enregistrée chez le transporteur : les journaux des transporteurs affichent chaque mise à jour reçue, ou la raison de son refus (par exemple un secret erroné). Les autres transporteurs sont vérifiés selon la planification définie dans les paramètres des transporteurs, et « Vérifier le statut maintenant » interroge immédiatement.',
'Cr_Guide_Q_Stuck' => 'Une expédition affiche une erreur de vérification du statut',
'Cr_Guide_A_Stuck' => 'Le transporteur a refusé les dernières vérifications ; la raison figure sur l’expédition et dans les journaux des transporteurs. Après plusieurs échecs, une expédition n’est plus vérifiée automatiquement : corrigez la cause, puis utilisez « Vérifier le statut maintenant ».',
'Cr_Guide_Q_Label' => 'Rien ne s’ouvre lors de l’impression d’une étiquette',
'Cr_Guide_A_Label' => 'Votre navigateur a bloqué la fenêtre pop-up. Autorisez les fenêtres pop-up pour ce site et réessayez.',
'Cr_Guide_Q_Cod' => 'Un reversement COD n’a pas été enregistré sur la vente',
'Cr_Guide_A_Cod' => 'Dans les paramètres des transporteurs, le paiement à la livraison nécessite que l’option soit activée et qu’un compte soit choisi. Sans compte, les reversements sont seulement marqués comme reversés.',
