'Tfa_Reset_Help' => ':name se connectera avec son seul mot de passe et pourra ensuite reconfigurer son application d’authentification. Ne le faites qu’après avoir confirmé l’identité du demandeur.',
'Tfa_Guide_Lead' => 'L’authentification à deux facteurs (2FA) ajoute une seconde étape à la connexion : après le mot de passe, le personnel saisit un code à 6 chiffres provenant d’une application d’authentification sur son téléphone. Un mot de passe volé ou deviné ne suffit plus pour se connecter.',
'Tfa_Guide_State_Required' => 'Obligatoire',
