'Tfa_Guide_App_Title' => 'Installer une application d’authentification',
'Tfa_Guide_App_Text' => 'Toute application prenant en charge les codes standard à 6 chiffres (TOTP) convient. Elles sont gratuites et fonctionnent hors ligne :',
'Tfa_Guide_Enable_Title' => 'L’activer depuis le profil',
'Tfa_Guide_Enable_1' => 'Ouvrez le Profil (menu de l’avatar en haut à droite) et trouvez la carte « Authentification à deux facteurs ».',
'Tfa_Guide_Enable_2' => 'Cliquez sur « Activer » et confirmez avec le mot de passe actuel.',
'Tfa_Guide_Enable_3' => 'Scannez le code QR avec l’application, ou saisissez la clé affichée en dessous.',
'Tfa_Guide_Enable_4' => 'Saisissez le code à 6 chiffres affiché par l’application pour terminer.',
'Tfa_Guide_Open_Profile' => 'Ouvrir mon profil',
'Tfa_Guide_Codes_Title' => 'Enregistrer les codes de récupération',
'Tfa_Guide_Codes_Text' => 'Juste après la configuration, 8 codes de récupération sont affichés une seule fois. Chacun remplace une seule fois un code du téléphone — en cas de téléphone perdu, cassé ou réinitialisé. Téléchargez-les ou copiez-les et conservez-les en lieu sûr, à l’écart du téléphone.',
'Tfa_Guide_Codes_Note' => 'Il en reste peu ? « Nouveaux codes de récupération » sur le profil remplace l’ensemble des codes ; les anciens cessent de fonctionner.',
'Tfa_Guide_Signin_Title' => 'Connexion',
'Tfa_Guide_Signin_Text' => 'Après l’e-mail et le mot de passe, la page de connexion demande le code actuel de l’application. Les codes changent toutes les 30 secondes et chacun ne fonctionne qu’une fois.',
'Tfa_Guide_Signin_Trust' => 'Cocher « Ne plus demander sur cet appareil » permet de ne plus saisir le code sur ce navigateur pendant :days jours.',
'Tfa_Guide_Signin_Recovery' => 'Pas de téléphone sous la main ? Cliquez sur « Utiliser un code de récupération » et saisissez l’un des codes enregistrés.',
'Tfa_Guide_Admin_Title' => 'Pour les administrateurs',
'Tfa_Guide_Require_Title' => 'La rendre obligatoire',
'Tfa_Guide_Require_Text' => 'Activez « Exiger l’authentification à deux facteurs » sur cette carte, puis choisissez les rôles qui doivent l’utiliser — ou laissez la liste vide pour tous les utilisateurs. Cliquez sur Envoyer pour enregistrer.',
'Tfa_Guide_Require_Next' => 'Personne n’est déconnecté. Les utilisateurs qui n’ont pas encore la 2FA sont guidés dans la configuration sur la page de connexion lors de leur prochaine connexion, avant d’accéder à l’application, et y voient leurs codes de récupération.',
'Tfa_Guide_Require_Note' => 'Les utilisateurs pour qui elle est obligatoire ne peuvent pas la désactiver depuis leur profil.',
'Tfa_Guide_Trust_Title' => 'Appareils de confiance',
'Tfa_Guide_Trust_Text' => '« Mémoriser les appareils de confiance » définit pendant combien de temps un navigateur peut se passer du code après une connexion réussie. Choisissez « Toujours demander un code » pour les ordinateurs partagés ou publics, comme un POS en magasin.',
'Tfa_Guide_Trust_Note' => 'Réduire la durée raccourcit celle des appareils déjà approuvés ; désactiver ou réinitialiser la 2FA les oublie tous.',
'Tfa_Guide_Lost_Title' => 'Téléphone perdu et aucun code de récupération',
'Tfa_Guide_Lost_Text' => 'Sur la page Utilisateurs, les utilisateurs ayant la 2FA affichent « Activée » dans la colonne 2FA. Le bouton bouclier dans Actions la réinitialise : l’utilisateur se connecte avec son seul mot de passe et reconfigure l’application (ou y est invité, si elle est obligatoire).',
'Tfa_Guide_Lost_Warn' => 'Confirmez l’identité du demandeur avant de réinitialiser — une réinitialisation supprime la protection que la 2FA apporte à ce compte.',
'Tfa_Guide_Open_Users' => 'Ouvrir les utilisateurs',
'Tfa_Guide_Mobile_Title' => 'Application mobile et API',
'Tfa_Guide_Mobile_Text' => 'L’application mobile et le point de terminaison de jeton de l’API demandent le même code. Si la 2FA est obligatoire pour un utilisateur qui ne l’a pas encore configurée, il doit d’abord se connecter une fois sur le web pour le faire.',
'Tfa_Guide_Protect_Title' => 'Protection intégrée',
'Tfa_Guide_Protect_1' => '5 codes erronés bloquent la saisie de code pour cet utilisateur pendant 15 minutes, quels que soient les paramètres de verrouillage ci-dessus.',
'Tfa_Guide_Protect_2' => 'Chaque code et chaque code de récupération ne fonctionne qu’une seule fois.',
'Tfa_Guide_Protect_3' => 'Avec « Enregistrer l’activité de connexion » activé, les codes erronés apparaissent dans la liste d’activité de connexion sous « Code 2FA erroné ».',
'Tfa_Guide_Trouble_Title' => 'Dépannage',
'Tfa_Guide_Faq_Clock_Q' => '« Ce code n’est pas valide » avec un nouveau code',
'Tfa_Guide_Faq_Clock_A' => 'L’horloge du téléphone est probablement décalée. Les codes dépendent de l’heure : réglez la date et l’heure du téléphone en automatique (heure réseau), puis essayez le code suivant.',
'Tfa_Guide_Faq_Phone_Q' => 'Passer à un nouveau téléphone',
'Tfa_Guide_Faq_Phone_A' => 'Utilisez la fonction de transfert de l’application d’authentification, ou désactivez la 2FA sur le profil puis réactivez-la avec le nouveau téléphone (si elle est obligatoire, demandez plutôt à un administrateur de la réinitialiser).',
'Tfa_Guide_Faq_Locked_Q' => '« Trop de codes invalides »',
'Tfa_Guide_Faq_Locked_A' => 'Attendez le délai indiqué (jusqu’à 15 minutes), ou demandez à un administrateur de réinitialiser la 2FA de l’utilisateur.',
'Tfa_Guide_Faq_Key_Q' => 'Personne ayant la 2FA ne peut se connecter après un changement de serveur',
'Tfa_Guide_Faq_Key_A' => 'Les secrets 2FA sont chiffrés avec l’APP_KEY du fichier .env. Conservez la même APP_KEY lors d’un déplacement ou d’une restauration de l’application ; si elle a changé, un administrateur sans 2FA doit réinitialiser les utilisateurs concernés.',
'Tfa_Guide_Button' => 'Guide',
