'Tfa_Guide_Rollout_Title' => 'Déployer pour tous les utilisateurs',
'Tfa_Guide_Rollout_1' => 'Activez-la d’abord sur votre propre compte (Profil), pour connaître les étapes.',
'Tfa_Guide_Rollout_2' => 'Indiquez à votre équipe quelle application installer et que la configuration prend une minute à la connexion.',
'Tfa_Guide_Rollout_3' => 'Activez « Exiger l’authentification à deux facteurs », laissez « Obligatoire pour » vide (= tous les utilisateurs) et choisissez éventuellement un délai de grâce. Cliquez sur Envoyer.',
'Tfa_Guide_Rollout_4' => 'Cliquez sur « Déconnecter les utilisateurs sans 2FA » pour que les personnes déjà connectées la configurent maintenant plutôt qu’à une connexion ultérieure. Vous restez connecté.',
'Tfa_Guide_Rollout_5' => 'Suivez la progression grâce au compteur de cette carte, ou au filtre « Configuration requise » de la page Utilisateurs.',
'Tfa_Guide_Rollout_Note' => 'Avec un délai de grâce, l’écran de configuration affiche « Me le rappeler plus tard » jusqu’à l’échéance ; ensuite, la configuration est obligatoire pour se connecter.',
'Tfa_Guide_Customers_Title' => 'Comptes clients (boutique et portail client)',
'Tfa_Guide_Customers_Text' => 'Les clients peuvent aussi protéger leur propre compte. C’est facultatif pour chaque client et jamais imposé : activez l’option dans Paramètres de la boutique → Contrôle d’accès à l’inscription (boutique en ligne) et dans Portail client → Paramètres du portail (portail client).',
'Tfa_Guide_Customers_1' => 'Les clients l’activent depuis Mon compte (boutique) ou Profil (portail).',
'Tfa_Guide_Customers_2' => 'Ils choisissent un code envoyé par e-mail — le plus simple, aucune application nécessaire — ou une application d’authentification avec des codes de récupération.',
'Tfa_Guide_Customers_3' => 'Les codes envoyés par e-mail nécessitent des paramètres de messagerie fonctionnels (Paramètres → Paramètres de messagerie). Ils expirent au bout de 10 minutes.',
'Tfa_Guide_Customers_4' => 'Désactiver l’option par la suite empêche les nouvelles configurations ; les clients qui l’utilisent déjà continuent d’être sollicités et peuvent la désactiver eux-mêmes.',
'Tfa_Required_Grace_Notice' => 'Votre administrateur exige l’authentification à deux facteurs. Vous pouvez la reporter à la connexion jusqu’au :date ; ensuite, la configuration sera obligatoire.',
'Tfa_Filter_All' => '2FA : tous les utilisateurs',
