'Sec_2fa_Grace' => 'Délai de grâce',
'Sec_2fa_Grace_Help' => 'Permet aux utilisateurs de choisir « Me le rappeler plus tard » sur l’écran de configuration jusqu’à l’échéance, afin que personne ne soit bloqué en pleine journée de travail. Compté à partir de l’activation de l’exigence.',
